import { Segmented } from '@refy-design/web';
import type { ComponentProps } from 'react';
const views = [
  { value: 'list', label: 'List' },
  { value: 'kanban', label: 'Kanban' },
  { value: 'timeline', label: 'Timeline' },
];
export function Example() {
  const args: Pick<
    ComponentProps<typeof Segmented>,
    'options' | 'label' | 'defaultValue'
  > = { options: views, label: 'Overview', defaultValue: 'list' };
  return <Segmented {...args} />;
}

import { Segmented } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
const views = [
  { value: 'list', label: 'List' },
  { value: 'kanban', label: 'Kanban' },
  { value: 'timeline', label: 'Timeline' },
];
export function Example() {
  const args: Pick<ComponentProps<typeof Segmented>, 'options' | 'label'> = {
    options: views,
    label: 'Overview',
  };
  const [view, setView] = useState('kanban');
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 12,
        alignItems: 'flex-start',
      }}
    >
      <Segmented {...args} value={view} onChange={setView} />
      <code
        style={{
          fontFamily: 'var(--font-mono)',
          fontSize: 12,
          color: 'var(--ink-3)',
        }}
      >
        {view}
      </code>
    </div>
  );
}

import { Segmented } from '@refy-design/web';
import type { ComponentProps } from 'react';
const views = [
  { value: 'list', label: 'List' },
  { value: 'kanban', label: 'Kanban' },
  { value: 'timeline', label: 'Timeline' },
];
export function Example() {
  const args: Pick<ComponentProps<typeof Segmented>, 'label' | 'options'> = {
    label: 'Overview',
    options: [...views.slice(0, 2), { value: 'map', label: 'Map', disabled: true }],
  };
  return <Segmented {...args} />;
}
